    print('red: NameError')

def is_overdue(days_late, limit):
    return days_late > limit

print('green: %s' % is_overdue(4, 3))

CASES = [((4, 3), True), ((3, 3), False), ((0, 5), False)]

def run_suite(fn):
    failed = 0
    for (days, limit), want in CASES:
        if fn(days, limit) != want:
            failed += 1
    return failed

try:
    run_suite(is_overdue)
    print('red: suite passed unexpectedly')
except NameError:
    print('red: NameError - failure is the missing behavior')

def is_overdue(days_late, grace_days):
    return days_late > grace_days

failed = run_suite(is_overdue)
print('green: failures %d' % failed)

def is_overdue(days_late, grace_days):
    # renamed for clarity; behavior unchanged
    return days_late > grace_days

print('refactor: failures %d' % run_suite(is_overdue))

